os.makedirs('static/icons', exist_ok=True)
for name, content in icons.items():
    path = os.path.join('static', 'icons', name)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)

print(f"Created {len(icons)} SVG icons successfully.")
